select 'a3300000-0000-4000-8000-000000000001','a3200000-0000-4000-8000-000000000001',51,'cash','SYNTHETIC-REPORT-'||n,'a3100000-0000-4000-8000-000000000001','2026-09-20 10:00+04' from generate_series(1,251) n;
create function pg_temp.report(b uuid default 'a3200000-0000-4000-8000-000000000001') returns jsonb language sql as $$ select public.business_report('2026-09-20','2026-09-20',b) $$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a3100000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select pg_temp.report()$$,'42501',null,'Owner requires actual AAL2 in clean migration replay');
select set_config('request.jwt.claims','{"sub":"a3100000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
