select count(*) from (select id from public.commercial_payments order by id limit 200 offset 200) p;
select is(pg_temp.report()-'asOf',current_setting('test.report')::jsonb-'asOf','Opening detail page cannot alter totals or transaction snapshot');
select is((pg_temp.report('a3200000-0000-4000-8000-000000000002')->'finance'->>'receivedMinor')::bigint,0::bigint,'Other branch excludes every payment');
