select is(pg_temp.report()->'finance','null'::jsonb,'Sales sees no family financial aggregates');
select set_config('request.jwt.claims','{"sub":"a3100000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
